policies = {
    "org/1": {"roles/viewer": {"group:devs@example.com"}},
    "folder/10": {"roles/editor": {"user:ada@example.com"}},
    "project/analytics": {"roles/owner": {"user:grace@example.com"}},
}

parent = {
    "project/analytics": "folder/10",
    "folder/10": "org/1",
    "org/1": None,
}

def effective_roles(resource, principal):
    roles = set()
    node = resource
    while node is not None:
        for role, principals in policies.get(node, {}).items():
            if principal in principals:
                roles.add(role)
        node = parent.get(node)
    return roles

for principal in ["user:ada@example.com", "group:devs@example.com", "user:grace@example.com"]:
    roles = sorted(effective_roles("project/analytics", principal))
    print(principal, "->", roles)
